off_patch:
def d(n):
	while len(str(n))!=1:
		n = sum(int(d) for d in str(n))
	return n

n_1 = int(input())
q, r = divmod(n_1, 9)
dcnt = [q] + [q + 1] * r + [q] * (8 - r)
res = 0
for di in range(9):
    for dj in range(9):
        res += dcnt[di] * dcnt[dj] * dcnt[di * dj % 9]
for ii in range(1, n_1 + 1):
    res -= n_1 // ii
print(res)

